<section class="admin-panel"><h1>Страницы</h1><div class="table-wrap"><table><tr><th>ID</th><th>Title</th><th>URL</th><th>Статус</th></tr><?php foreach($pages as $p): ?><tr><td><?= (int)$p['id'] ?></td><td><?= e($p['title']) ?></td><td>/<?= e($p['slug']) ?>/</td><td><?= !empty($p['is_published'])?'Опубликована':'Черновик' ?></td></tr><?php endforeach; ?></table></div><h2>Добавить/обновить страницу</h2><form method="post" class="admin-form grid wide"><?= App\Core\Csrf::field() ?><input type="hidden" name="action" value="save_page"><label>ID для обновления<input name="id" type="number"></label><label>Название<input name="title" required></label><label>URL slug<input name="slug" required></label><label>Title<input name="meta_title"></label><label>Description<input name="meta_description"></label><label>H1<input name="h1"></label><label>Canonical<input name="canonical_url"></label><label><input type="checkbox" name="robots_index" value="1" checked> Индексировать</label><label><input type="checkbox" name="is_published" value="1" checked> Опубликовать</label><label class="full">HTML текст<textarea name="body" rows="10"></textarea></label><button class="btn btn-primary">Сохранить</button></form></section>
